"use strict";(self.webpackChunkbast_docu=self.webpackChunkbast_docu||[]).push([[235],{88817:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"beta-26.2","metadata":{"permalink":"/dadadocu/dadaprogressions-changelog/beta-26.2","source":"@site/dadaprogressions-changelog/2026-07-04-beta-26.2.md","title":"DadaProgressions Beta 26.2","description":"Beta 26.2 is mainly focused on making goal management easier and safer for server owners.","date":"2026-07-04T00:00:00.000Z","tags":[{"inline":true,"label":"dadaprogressions","permalink":"/dadadocu/dadaprogressions-changelog/tags/dadaprogressions"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaProgressions Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"beta-26.2","title":"DadaProgressions Beta 26.2","authors":["mrbast"],"tags":["dadaprogressions"]},"unlisted":false,"nextItem":{"title":"DadaProgressions Beta 26.1","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.1"}},"content":"Beta 26.2 is mainly focused on making goal management easier and safer for server owners.\\n\\n\x3c!-- truncate --\x3e\\n\\n## A better goal editor\\n\\nThe `/dp admin editor` menu has been expanded quite a bit. You can now manage most parts of a goal without having to edit the YAML by hand.\\n\\n- Rename, duplicate, enable, disable, or delete goals.\\n- Change the scope, period, event type, and target.\\n- Add and remove criteria from composite goals.\\n- Configure global filters or filters for a specific criterion.\\n- Switch composite goals between `AND` and `OR`.\\n- Add prerequisites and choose between `ALL` and `ANY`.\\n\\nTargets can be entered with a small in-game keypad. Materials, entities, worlds, game modes, damage causes, attribution values, and prerequisite goals have their own paginated selection menus. Chat input is still available when you need to enter a custom value.\\n\\n## Safer editing and reloads\\n\\nChanges made through the editor are validated before they are kept. If something is wrong, the plugin restores the previous file and keeps the working goals loaded.\\n\\n`/dp admin validate` checks the goal files without applying them. `/dp admin reload` also keeps the current configuration active when one of the new files contains an error.\\n\\nThe validation report now covers malformed YAML, duplicate or invalid IDs, unsupported filter values, missing prerequisites, missing tiers, and circular prerequisite chains.\\n\\n## DadaPlatform 26.2\\n\\nDadaPlatform has been updated from 26.0 to 26.2. This update improves the shared handling of chat messages, action bars, and MiniMessage formatting while keeping the fallbacks used by older servers.\\n\\nSome groundwork for Folia is included in the platform layer, but DadaProgressions does not claim full Folia support yet.\\n\\n## Updating\\n\\nStop the server, replace the old plugin with `DadaProgressions-beta-26.2.jar`, and start it again. Your existing simple goals do not need to be changed.\\n\\nAs always, make a backup first and run `/dp admin validate` after updating.\\n\\nThe plugin jar is still built for Java 8. Your server may require a newer Java version depending on the Minecraft version you are running."},{"id":"beta-26.1","metadata":{"permalink":"/dadadocu/dadaprogressions-changelog/beta-26.1","source":"@site/dadaprogressions-changelog/2026-07-01-beta-26.1.md","title":"DadaProgressions Beta 26.1","description":"Beta 26.1 makes goals much more flexible and improves how progress notifications are delivered during busy sessions.","date":"2026-07-01T00:00:00.000Z","tags":[{"inline":true,"label":"dadaprogressions","permalink":"/dadadocu/dadaprogressions-changelog/tags/dadaprogressions"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaProgressions Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"beta-26.1","title":"DadaProgressions Beta 26.1","authors":["mrbast"],"tags":["dadaprogressions"]},"unlisted":false,"prevItem":{"title":"DadaProgressions Beta 26.2","permalink":"/dadadocu/dadaprogressions-changelog/beta-26.2"}},"content":"Beta 26.1 makes goals much more flexible and improves how progress notifications are delivered during busy sessions.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Modular goals\\n\\nGoals can now contain multiple criteria joined with `AND` or `OR`. Each criterion keeps its own progress, so a goal can ask players to complete several different tasks or let them choose between alternatives.\\n\\nFilters are available for materials, entities, worlds, game modes, permissions, commands, damage causes, and player attribution. Point rules can also assign fixed values or multipliers to specific actions.\\n\\nExisting single-type goals continue to work without changes.\\n\\n## Goal chains\\n\\nGoals can depend on other goals. A prerequisite may require the player to have completed a goal during the current period or at any point in the past.\\n\\nInvalid chains, missing prerequisites, and circular dependencies are reported when goals are loaded.\\n\\n## New community goal examples\\n\\nThe default configuration now includes four examples built with the modular goal engine:\\n\\n- `community_daily_supply_run`\\n- `community_weekly_beast_cleanup`\\n- `community_weekly_breeding_festival`\\n- `community_monthly_monument_project`\\n\\nAnimal breeding is now tracked automatically, including attribution for older server versions.\\n\\n## Clearer goal list\\n\\nGoal entries now show a short description of the actual objective. Their lore supports live progress and target placeholders, while the more technical details remain in the individual goal view.\\n\\nExtended state lore is hidden by default. It can be restored with `gui.list.goal-item.show-state-lore`.\\n\\n## Notification queues\\n\\nChat, action bar, title, and boss bar notifications now use separate queues. Repeated updates for the same goal are combined, preserving the starting value and total progress gained instead of filling the screen with one message per action.\\n\\nQueue timing, size, and channel limits can be configured globally, for a specific event, or for an individual goal.\\n\\n## Chat batching\\n\\nUpdates from several goals can be grouped into a single chat message while keeping their original order. The separator and maximum number of entries are configurable; setting `chat-batch.max-entries` to `0` includes every pending entry.\\n\\n```text\\nDaily Builder: 35 -> 45/128 (+10) | Community Weekly Build: 40 -> 50/5000 (+10)\\n```\\n\\nChat batching is enabled by default and can be overridden globally, per event, or per goal."}]}}')}}]);